extension Ws.Device.Remote {
    /// The device listener: loopback only or every interface, and whether it listens; diagnostics say where it is
    /// bound, what devices are told, what the host firewall looks like (read-only, null when unknown) and when a device
    /// last connected from a public address.
    public enum Status: WsRequest {
        public static let command = WsCommand.deviceRemoteStatus
        /// The daemon reads nothing; the payload is sent as null.
        public typealias Payload = WsNoPayload

        public struct Response: Codable, Hashable, Sendable {
            /// The device listener as configured and as it is.
            public var status: Status
            /// transfer-protocol.md §1.3. Optional for older daemons: the compatibility baseline doesn't guarantee it.
            public var diagnostics: Diagnostics?

            public init(status: Status, diagnostics: Diagnostics? = nil) {
                self.status = status
                self.diagnostics = diagnostics
            }

            enum CodingKeys: String, CodingKey {
                case status
