                    self.remote = try container.decode(Bool.self, forKey: .remote)
                    self.port = try container.decode(Int64.self, forKey: .port)
                    self.listening = try container.decode(Bool.self, forKey: .listening)
                    self.address = try container.decode(String?.self, forKey: .address)
                    self.error = try container.decode(String?.self, forKey: .error)
                    self.serverSpkiSha256 = try container.decode(String?.self, forKey: .serverSpkiSha256)
                    self.connections = try container.decode(Int64.self, forKey: .connections)
                }

