                    var container = encoder.container(keyedBy: CodingKeys.self)
                    try container.encode(self.enabled, forKey: .enabled)
                    try container.encode(self.remote, forKey: .remote)
                    try container.encode(self.port, forKey: .port)
                    try container.encode(self.listening, forKey: .listening)
                    try container.encode(self.address, forKey: .address)
                    try container.encode(self.error, forKey: .error)
                    try container.encode(self.serverSpkiSha256, forKey: .serverSpkiSha256)
                    try container.encode(self.connections, forKey: .connections)
                }
            }

            public struct Diagnostics: Codable, Hashable, Sendable {
                /// Every address it listens on ("[::]:36972", "127.0.0.1:36972").
                public var bind: [String]
                /// An IPv6 socket is among them.
                public var ipv6: Bool
                /// Ordered loopback, lan, vpn, wan, passthrough; de-duplicated by (host, port); at most 32. Only
                /// loopback interface addresses while remote is off; configured names always.
                public var candidates: [Candidate]
                public var firewall: Firewall
                /// Unix seconds of the latest Device handshake from a public (non-loopback, non-private) address since
                /// the daemon started; null when none. Minimum 0. Always sent; nil is null.
                public var lastRemoteDeviceAt: Int64?
                /// Always sent; nil is null.
                public var lastRemoteDeviceIP: String?

                public init(bind: [String], ipv6: Bool, candidates: [Candidate], firewall: Firewall,
                            lastRemoteDeviceAt: Int64? = nil, lastRemoteDeviceIP: String? = nil) {
                    self.bind = bind
                    self.ipv6 = ipv6
                    self.candidates = candidates
                    self.firewall = firewall
                    self.lastRemoteDeviceAt = lastRemoteDeviceAt
                    self.lastRemoteDeviceIP = lastRemoteDeviceIP
                }

                enum CodingKeys: String, CodingKey {
                    case bind
                    case ipv6
                    case candidates
                    case firewall
                    case lastRemoteDeviceAt = "last_remote_device_at"
                    case lastRemoteDeviceIP = "last_remote_device_ip"
                }

                public init(from decoder: any Decoder) throws {
                    let container = try decoder.container(keyedBy: CodingKeys.self)
                    self.bind = try container.decode([String].self, forKey: .bind)
                    self.ipv6 = try container.decode(Bool.self, forKey: .ipv6)
                    self.candidates = try container.decode([Candidate].self, forKey: .candidates)
                    self.firewall = try container.decode(Firewall.self, forKey: .firewall)
                    self.lastRemoteDeviceAt = try container.decode(Int64?.self, forKey: .lastRemoteDeviceAt)
                    self.lastRemoteDeviceIP = try container.decode(String?.self, forKey: .lastRemoteDeviceIP)
                }

                public func encode(to encoder: any Encoder) throws {
                    var container = encoder.container(keyedBy: CodingKeys.self)
                    try container.encode(self.bind, forKey: .bind)
                    try container.encode(self.ipv6, forKey: .ipv6)
                    try container.encode(self.candidates, forKey: .candidates)
                    try container.encode(self.firewall, forKey: .firewall)
                    try container.encode(self.lastRemoteDeviceAt, forKey: .lastRemoteDeviceAt)
                    try container.encode(self.lastRemoteDeviceIP, forKey: .lastRemoteDeviceIP)
                }

                public struct Candidate: Codable, Hashable, Sendable {
                    /// Host name or IP literal (IPv6 unbracketed).
                    public var host: String
                    /// Minimum 0. Maximum 65535.
                    public var port: Int64
                    /// Address class: loopback, RFC 1918 / ULA (lan), 100.64/10 or a VPN interface (vpn), other global
                    /// unicast (wan), a TLS passthrough (passthrough). One of the known values in `Kind`; a newer
                    /// daemon may send others.
                    public var kind: String
                    /// One of the known values in `Source`; a newer daemon may send others.
                    public var source: String
                    /// The interface it was read from (source interface only).
                    public var interface: String?

                    public init(host: String, port: Int64, kind: String, source: String, interface: String? = nil) {
                        self.host = host
                        self.port = port
                        self.kind = kind
                        self.source = source
                        self.interface = interface
                    }

                    enum CodingKeys: String, CodingKey {
                        case host
                        case port
                        case kind
                        case source
                        case interface
                    }

                    /// Known values (the member stays a String: a newer daemon may send others).
                    public enum Kind {
                        public static let loopback = "loopback"
                        public static let lan = "lan"
                        public static let vpn = "vpn"
                        public static let wan = "wan"
                        public static let passthrough = "passthrough"
                        public static let allValues: [String] = [loopback, lan, vpn, wan, passthrough]
                    }

                    /// Known values (the member stays a String: a newer daemon may send others).
                    public enum Source {
                        public static let interface = "interface"
                        public static let mdns = "mdns"
                        public static let config = "config"
                        public static let allValues: [String] = [interface, mdns, config]
                    }
                }

                public struct Firewall: Codable, Hashable, Sendable {
                    /// One of the known values in `Detected`; a newer daemon may send others.
                    public var detected: String
                    /// Null when it can't be told without root. Always sent; nil is null.
                    public var active: Bool?
                    /// What to run so the port gets through, if known. Always sent; nil is null.
                    public var hint: String?

                    public init(detected: String, active: Bool? = nil, hint: String? = nil) {
                        self.detected = detected
                        self.active = active
                        self.hint = hint
                    }

                    enum CodingKeys: String, CodingKey {
                        case detected
                        case active
                        case hint
                    }

                    public init(from decoder: any Decoder) throws {
                        let container = try decoder.container(keyedBy: CodingKeys.self)
                        self.detected = try container.decode(String.self, forKey: .detected)
                        self.active = try container.decode(Bool?.self, forKey: .active)
                        self.hint = try container.decode(String?.self, forKey: .hint)
                    }

                    public func encode(to encoder: any Encoder) throws {
                        var container = encoder.container(keyedBy: CodingKeys.self)
                        try container.encode(self.detected, forKey: .detected)
                        try container.encode(self.active, forKey: .active)
                        try container.encode(self.hint, forKey: .hint)
                    }

                    /// Known values (the member stays a String: a newer daemon may send others).
                    public enum Detected {
                        public static let ufw = "ufw"
                        public static let firewalld = "firewalld"
                        public static let nftables = "nftables"
                        public static let pf = "pf"
                        public static let alf = "alf"
                        public static let none = "none"
                        public static let unknown = "unknown"
                        public static let allValues: [String] = [ufw, firewalld, nftables, pf, alf, none, unknown]
                    }
                }
            }
        }
    }
}

